Write {"file_path":"D:\code\astrorepo\src\main\db\fts.ts","content":"import Database from 'better-sqlite3'

export function initFts(sqlite: Database.Database): void {
  sqlite.exec(`
    CREATE VIRTUAL TABLE IF NOT EXISTS targets_fts USING fts5(
      canonical_name,
      aliases,
      description,
      constellation,
      content='',
      tokenize='unicode61 remove_diacritics 2'
    );
  `)

  const hasTriggers = sqlite
    .prepare("SELECT count(*) as cnt FROM sqlite_master WHERE type='trigger' AND name='targets_fts_insert'")
    .get() as { cnt: number }

  if (hasTriggers.cnt === 0) {
    sqlite.exec(`
      CREATE TRIGGER targets_fts_insert AFTER INSERT ON targets BEGIN
        INSERT INTO targets_fts(rowid, canonical_name, aliases, description, constellation)
        VALUES (
          new.rowid,
          new.canonical_name,
          COALESCE((SELECT group_concat(alias, ' | ') FROM target_aliases WHERE target_id = new.id), ''),
          COALESCE(new.description, ''),
          COALESCE(new.constellation, '')
        );
      END;

      CREATE TRIGGER targets_fts_delete AFTER DELETE ON targets BEGIN
        INSERT INTO targets_fts(targets_fts, rowid, canonical_name, aliases, description, constellation)
        VALUES (
          'delete',
          old.rowid,
          old.canonical_name,
          COALESCE((SELECT group_concat(alias, ' | ') FROM target_aliases WHERE target_id = old.id), ''),
          COALESCE(old.description, ''),
          COALESCE(old.constellation, '')
        );
      END;

      CREATE TRIGGER targets_fts_update AFTER UPDATE ON targets BEGIN
        INSERT INTO targets_fts(targets_fts, rowid, canonical_name, aliases, description, constellation)
        VALUES (
          'delete',
          old.rowid,
          old.canonical_name,
          COALESCE((SELECT group_concat(alias, ' | ') FROM target_aliases WHERE target_id = old.id), ''),
          COALESCE(old.description, ''),
          COALESCE(old.constellation, '')
        );
        INSERT INTO targets_fts(rowid, canonical_name, aliases, description, constellation)
        VALUES (
          new.rowid,
          new.canonical_name,
          COALESCE((SELECT group_concat(alias, ' | ') FROM target_aliases WHERE target_id = new.id), ''),
          COALESCE(new.description, ''),
          COALESCE(new.constellation, '')
        );
      END;

      CREATE TRIGGER target_alias_insert AFTER INSERT ON target_aliases BEGIN
        UPDATE targets SET updated_at = datetime('now') WHERE id = new.target_id;
      END;

      CREATE TRIGGER target_alias_delete AFTER DELETE ON target_aliases BEGIN
        UPDATE targets SET updated_at = datetime('now') WHERE id = old.target_id;
      END;
    `)
  }
}

export function rebuildFtsIndex(sqlite: Database.Database): void {
  sqlite.exec("DELETE FROM targets_fts;")
  sqlite.exec(`
    INSERT INTO targets_fts(rowid, canonical_name, aliases, description, constellation)
    SELECT
      t.rowid,
      t.canonical_name,
      COALESCE((SELECT group_concat(ta.alias, ' | ') FROM target_aliases ta WHERE ta.target_id = t.id), ''),
      COALESCE(t.description, ''),
      COALESCE(t.constellation, '')
    FROM targets t;
  `)
}
"}

Write {"file_path":"D:\code\astrorepo\src\main\ipc\handlers.ts","content":"import { ipcMain, IpcMainInvokeEvent } from 'electron'

type HandlerFn = (event: IpcMainInvokeEvent, ...args: unknown[]) => Promise<unknown>

const registeredChannels: string[] = []

export function handle(channel: string, handler: HandlerFn): void {
  ipcMain.handle(channel, handler)
  registeredChannels.push(channel)
}

export function registerIpcHandlers(): void {
  // Services register their own handlers by calling handle() directly.
  // This function is the single entry point called from main/index.ts
  // to ensure all service modules are loaded and their handlers registered.
}

export function getRegisteredChannels(): string[] {
  return [...registeredChannels]
}
"}

Write {"file_path":"D:\code\astrorepo\src\renderer\hooks\useIPC.ts","content":"import { useState, useCallback } from 'react'

declare global {
  interface Window {
    api: {
      invoke: (channel: string, ...args: unknown[]) => Promise<unknown>
    }
  }
}

interface UseIPCState<T> {
  data: T | null
  loading: boolean
  error: string | null
}

interface UseIPCReturn<T> extends UseIPCState<T> {
  execute: (...args: unknown[]) => Promise<T>
  reset: () => void
}

export function useIPC<T>(channel: string): UseIPCReturn<T> {
  const [state, setState] = useState<UseIPCState<T>>({
    data: null,
    loading: false,
    error: null
  })

  const execute = useCallback(
    async (...args: unknown[]): Promise<T> => {
      setState({ data: null, loading: true, error: null })
      try {
        const result = (await window.api.invoke(channel, ...args)) as T
        setState({ data: result, loading: false, error: null })
        return result
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err)
        setState({ data: null, loading: false, error: message })
        throw err
      }
    },
    [channel]
  )

  const reset = useCallback(() => {
    setState({ data: null, loading: false, error: null })
  }, [])

  return { ...state, execute, reset }
}

export async function invoke<T>(channel: string, ...args: unknown[]): Promise<T> {
  return (await window.api.invoke(channel, ...args)) as T
}
"}

