  if (!obs) return emptyVisibility()

  const observer = new Astronomy.Observer(obs.latitude, obs.longitude, obs.altitude_m)
  const date = new Date(dateStr + 'T12:00:00Z')
  const astroDate = Astronomy.MakeTime(date)

