Write {"file_path":"D:\code\astrorepo\src\main\services\dashboard.ts","content":"import { getSqlite } from '../db/connection'
import type { DashboardStats, CatalogueProgress } from '@shared/types'

export function getDashboardStats(): DashboardStats {
  const sqlite = getSqlite()

  const totals = sqlite.prepare(
    `SELECT
       COUNT(*) as total,
       COUNT(CASE WHEN workflow_stage IN ('published','printed','archived') THEN 1 END) as completed,
       COUNT(CASE WHEN workflow_stage NOT IN ('planned','published','printed','archived') THEN 1 END) as in_progress,
       COUNT(CASE WHEN workflow_stage = 'planned' THEN 1 END) as planned
     FROM targets`
  ).get() as Record<string, number>

  const typeRows = sqlite.prepare(
    'SELECT object_type, COUNT(*) as cnt FROM targets GROUP BY object_type'
  ).all() as Array<{ object_type: string; cnt: number }>

  const objectsByType: Record<string, number> = {}
  for (const r of typeRows) objectsByType[r.object_type] = r.cnt

  const catRows = sqlite.prepare(
    `SELECT c.abbreviation,
            COUNT(ce.id) as total,
            COUNT(CASE WHEN t.workflow_stage IN ('published','printed','archived') THEN 1 END) as completed
     FROM catalogues c
     LEFT JOIN catalogue_entries ce ON ce.catalogue_id = c.id
     LEFT JOIN targets t ON t.id = ce.target_id
     GROUP BY c.id`
  ).all() as Array<{ abbreviation: string; total: number; completed: number }>

  const objectsByCatalogue: Record<string, { completed: number; total: number }> = {}
  for (const r of catRows) objectsByCatalogue[r.abbreviation] = { completed: r.completed, total: r.total }

  const sessionStats = sqlite.prepare(
    `SELECT COUNT(DISTINCT date) as nights,
            COALESCE(SUM(total_exposure_sec), 0) as total_exposure
     FROM observation_sessions`
  ).get() as { nights: number; total_exposure: number }

  const equipRows = sqlite.prepare(
    `SELECT e.name, COUNT(se.session_id) as session_count
     FROM equipment e
     JOIN session_equipment se ON se.equipment_id = e.id
     GROUP BY e.id
     ORDER BY session_count DESC
     LIMIT 5`
  ).all() as Array<{ name: string; session_count: number }>

  return {
    totalTargets: totals.total,
    completedTargets: totals.completed,
    inProgressTargets: totals.in_progress,
    plannedTargets: totals.planned,
    objectsByType,
    objectsByCatalogue,
    observationNights: sessionStats.nights,
    totalFitsFiles: 0,
    totalExposureSec: sessionStats.total_exposure,
    storageBytes: 0,
    averageIntegrationSec: 0,
    mostUsedEquipment: equipRows.map((r) => ({ name: r.name, sessionCount: r.session_count })),
    largestDataset: null,
    deepestIntegration: null,
    longestProject: null,
    oldestUnfinished: null
  }
}

export function getCatalogueProgressStats(): CatalogueProgress[] {
  const sqlite = getSqlite()
  const rows = sqlite.prepare(
    `SELECT c.id as catalogue_id, c.name as catalogue_name, c.abbreviation,
            COUNT(ce.id) as total,
            COUNT(CASE WHEN t.workflow_stage IN ('published','printed','archived') THEN 1 END) as completed
     FROM catalogues c
     LEFT JOIN catalogue_entries ce ON ce.catalogue_id = c.id
     LEFT JOIN targets t ON t.id = ce.target_id
     GROUP BY c.id
     ORDER BY c.name`
  ).all() as Array<Record<string, unknown>>

  return rows.map((r) => ({
    catalogueId: r.catalogue_id as string,
    catalogueName: r.catalogue_name as string,
    abbreviation: r.abbreviation as string,
    completed: r.completed as number,
    total: r.total as number
  }))
}
"}

Write {"file_path":"D:\code\astrorepo\src\main\services\relationship.ts","content":"import { ulid } from 'ulid'
import { getSqlite } from '../db/connection'
import type { TargetRelationship, RelationshipWithTarget } from '@shared/types'

export function createRelationship(sourceTargetId: string, relatedTargetId: string, relationshipType: string): TargetRelationship {
  const sqlite = getSqlite()
  const id = ulid()
  const now = new Date().toISOString()

  sqlite
    .prepare('INSERT INTO target_relationships (id, source_target_id, related_target_id, relationship_type, created_at) VALUES (?, ?, ?, ?, ?)')
    .run(id, sourceTargetId, relatedTargetId, relationshipType, now)

  return {
    id,
    sourceTargetId,
    relatedTargetId,
    relationshipType: relationshipType as TargetRelationship['relationshipType'],
    createdAt: now
  }
}

export function listRelationships(targetId: string): RelationshipWithTarget[] {
  const sqlite = getSqlite()

  const rows = sqlite
    .prepare(
      `SELECT r.id, r.source_target_id, r.related_target_id, r.relationship_type, r.created_at,
              t.id as t_id, t.canonical_name, t.object_type, t.constellation, t.magnitude,
              t.workflow_stage, t.is_custom
       FROM target_relationships r
       JOIN targets t ON (
         CASE WHEN r.source_target_id = ? THEN t.id = r.related_target_id
              ELSE t.id = r.source_target_id END
       )
       WHERE r.source_target_id = ? OR r.related_target_id = ?`
    )
    .all(targetId, targetId, targetId) as Array<Record<string, unknown>>

  return rows.map((r) => {
    const isSource = r.source_target_id === targetId
    const aliases = sqlite
      .prepare('SELECT alias FROM target_aliases WHERE target_id = ?')
      .all(r.t_id as string) as { alias: string }[]

    const relType = r.relationship_type as string
    let displayType = relType.replace(/_/g, ' ')
    if (!isSource) {
      const inverses: Record<string, string> = {
        contains: 'contained in',
        parent_region: 'part of',
        nearby: 'nearby'
      }
      displayType = inverses[relType] ?? displayType
    }

    return {
      id: r.id as string,
      sourceTargetId: r.source_target_id as string,
      relatedTargetId: r.related_target_id as string,
      relationshipType: relType as RelationshipWithTarget['relationshipType'],
      createdAt: r.created_at as string,
      relatedTarget: {
        id: r.t_id as string,
        canonicalName: r.canonical_name as string,
        objectType: r.object_type as RelationshipWithTarget['relatedTarget']['objectType'],
        constellation: r.constellation as string | null,
        magnitude: r.magnitude as number | null,
        workflowStage: r.workflow_stage as string,
        isCustom: (r.is_custom as number) === 1,
        aliases: aliases.map((a) => a.alias)
      },
      displayType
    }
  })
}

export function deleteRelationship(id: string): boolean {
  const sqlite = getSqlite()
  const result = sqlite.prepare('DELETE FROM target_relationships WHERE id = ?').run(id)
  return result.changes > 0
}
"}

